<pre><code>{"type Note = {\n  id: string;\n  title: string;\n  description?: string;\n};\n\ntype NoteCardProps = {\n  note: Note;\n};\n\nfunction NoteCard({ note }: NoteCardProps) {\n  return (\n    <article>\n      <h2>{note.title}</h2>\n      <p>{note.description ?? \"Без описания\"}</p>\n    </article>\n  );\n}\n\nconst note: Note = {\n  id: \"1\",\n  title: \"План проекта\",\n};\n\nexport default function NotesPage() {\n  return <NoteCard note={note} />;\n}\n"}</code></pre>
<p>
